import {describe, it, expect} from 'vitest';
import {createChatOrchestrator} from './chatOrchestrator.js';
import type {OrchestratorHooks} from './chatOrchestrator.js';
import type {AIProvider, MessageChunk, SendMessageParams, UsageMetadata, ToolCall} from '../types/ai.js';
import type {ChatSession} from '../types/session.js';
import {PromptBuilder} from '../infrastructure/builders/promptBuilder.js';
import {ToolRegistry} from './tools/registry.js';

const SENT_AT = '2026-01-01T00:00:00.000Z';

function createSession(content: string): ChatSession {
  return {
    sessionId: 's1',
    userId: 'u1',
    entries: [{role: 'user', content, timestamp: SENT_AT}],
  };
}

const promptBuilder = new PromptBuilder({
  prompts: {
    system: () => 'System prompt',
    thinkingTag: {start: '', end: ''},
  },
  modelSupports: {
    systemPrompt: true,
    toolCallRoles: true,
  },
});

function registryReturning(resultText: string): ToolRegistry {
  const registry = new ToolRegistry();
  registry.register(
    {name: 'test_tool', description: 'A test tool', inputSchema: {type: 'object', properties: {}}},
    async () => ({result: resultText})
  );
  return registry;
}

const scriptedProvider = (rounds: MessageChunk[][]): AIProvider => {
  let round = 0;
  return {
    async *sendMessage(): AsyncGenerator<MessageChunk> {
      for (const chunk of rounds[round++] ?? []) yield chunk;
    },
    async generateStructured<T>(): Promise<T> {
      return {} as T;
    },
  };
};

const TOOL_CALL: MessageChunk = {
  type: 'tool_use',
  toolCall: {id: 'call_1', name: 'test_tool', input: {}},
};
const STOP_FOR_TOOL: MessageChunk = {type: 'stop', stopReason: 'tool_use'};
const STOP_DONE: MessageChunk = {type: 'stop', stopReason: 'end_turn'};

describe('Report usage across every tool round', () => {
  it('A turn driven through two tool rounds reports usage covering every provider call in that turn', async () => {
    let receivedUsage: any;
    const hooks: OrchestratorHooks = {
      afterModelResponse: async (_session, _text, usage) => {
        receivedUsage = usage;
      },
    };

    const orchestrator = createChatOrchestrator(
      scriptedProvider([
        // Round 1 (tool use)
        [TOOL_CALL, {type: 'stop', stopReason: 'tool_use', usage: {inputTokens: 10, outputTokens: 2, totalTokens: 12}}],
        // Round 2 (tool use)
        [TOOL_CALL, {type: 'stop', stopReason: 'tool_use', usage: {inputTokens: 15, outputTokens: 3, totalTokens: 18}}],
        // Round 3 (final answer)
        [
          {type: 'text', text: 'done'},
          {type: 'stop', stopReason: 'end_turn', usage: {inputTokens: 20, outputTokens: 5, totalTokens: 25}},
        ],
      ]),
      promptBuilder,
      registryReturning('result'),
      {hooks}
    );

    await orchestrator.processMessage(createSession('ask'));

    expect(receivedUsage).toEqual({
      inputTokens: 45,
      outputTokens: 10,
      totalTokens: 55,
      providerCalls: [
        {inputTokens: 10, outputTokens: 2, totalTokens: 12},
        {inputTokens: 15, outputTokens: 3, totalTokens: 18},
        {inputTokens: 20, outputTokens: 5, totalTokens: 25},
      ],
    });
  });

  it('A provider that reports no usage on some rounds does not make the total undefined or NaN', async () => {
    let receivedUsage: any;
    const hooks: OrchestratorHooks = {
      afterModelResponse: async (_session, _text, usage) => {
        receivedUsage = usage;
      },
    };

    const orchestrator = createChatOrchestrator(
      scriptedProvider([
        // Round 1 reports usage
        [TOOL_CALL, {type: 'stop', stopReason: 'tool_use', usage: {inputTokens: 10, outputTokens: 2, totalTokens: 12}}],
        // Round 2 reports NO usage
        [
          {type: 'text', text: 'done'},
          {type: 'stop', stopReason: 'end_turn'},
        ],
      ]),
      promptBuilder,
      registryReturning('result'),
      {hooks}
    );

    await orchestrator.processMessage(createSession('ask'));

    // Should only accumulate the rounds that provided usage
    expect(receivedUsage).toEqual({
      inputTokens: 10,
      outputTokens: 2,
      totalTokens: 12,
      providerCalls: [{inputTokens: 10, outputTokens: 2, totalTokens: 12}],
    });
  });

  it('A turn where nothing reported still reports nothing', async () => {
    let receivedUsage: any;
    const hooks: OrchestratorHooks = {
      afterModelResponse: async (_session, _text, usage) => {
        receivedUsage = usage;
      },
    };

    const orchestrator = createChatOrchestrator(
      scriptedProvider([
        [TOOL_CALL, {type: 'stop', stopReason: 'tool_use'}],
        [
          {type: 'text', text: 'done'},
          {type: 'stop', stopReason: 'end_turn'},
        ],
      ]),
      promptBuilder,
      registryReturning('result'),
      {hooks}
    );

    await orchestrator.processMessage(createSession('ask'));

    expect(receivedUsage).toBeUndefined();
  });
});

