  const r2: UsageMetadata = {inputTokens: 20, outputTokens: 5, totalTokens: 25};

  it('returns single-round usage unchanged, without providerCalls', () => {
    expect(accumulateUsage([r1])).toEqual({inputTokens: 10, outputTokens: 2, totalTokens: 12});
  });

  it('sums tokens and includes providerCalls for multi-round turns', () => {
    expect(accumulateUsage([r1, r2])).toEqual({
      inputTokens: 30,
      outputTokens: 7,
      totalTokens: 37,
      providerCalls: [r1, r2],
    });
  });

  it('omits rounds with no usage from the sum and providerCalls', () => {
    expect(accumulateUsage([r1, undefined])).toEqual({
      inputTokens: 10,
      outputTokens: 2,
      totalTokens: 12,
      providerCalls: [r1],
    });
  });

  it('returns undefined when no round reported usage', () => {
    expect(accumulateUsage([undefined, undefined])).toBeUndefined();
  });

  it('returns undefined for a single round with no usage', () => {
    expect(accumulateUsage([undefined])).toBeUndefined();
  });
});

